<script>
document.addEventListener('DOMContentLoaded',()=>{const table=document.querySelector('table');if(!table)return;const headers=[['Perusahaan','company_id'],['Form','form_key'],['Format','format'],['Counter','counter_scope'],['Status','is_active']];const params=new URLSearchParams(window.location.search);const current=params.get('sort');const direction=params.get('direction')==='desc'?'desc':'asc';table.querySelectorAll('thead th').forEach((th,index)=>{const item=headers[index];if(!item)return;const [label,column]=item;const next=current===column&&direction==='asc'?'desc':'asc';params.set('sort',column);params.set('direction',next);params.delete('page');const link=document.createElement('a');link.href=window.location.pathname+'?'+params.toString();link.className='text-decoration-none text-reset';link.textContent=label+(current===column?(direction==='asc'?' ↑':' ↓'):'');th.textContent='';th.appendChild(link);});});
</script>
